const MARK_ONLY_PATH = "M 17.445 52.697 L 0.000 87.292 L 17.445 87.292 L 34.890 52.697 L 17.445 52.697 Z M 52.187 35.252 L 26.019 87.292 L 43.465 87.292 L 69.632 35.252 L 52.187 35.252 Z M 104.375 52.549 L 113.245 35.178 L 104.375 17.807 L 86.930 17.807 L 52.040 87.291 L 69.485 87.291 L 95.652 35.178 L 104.375 52.549 Z M 150.615 0.000 L 122.320 17.806 L 130.944 17.806 L 104.618 69.994 L 96.287 52.549 L 87.476 69.994 L 95.881 87.291 L 113.667 87.291 L 148.618 17.806 L 157.151 17.806 L 150.615 0.000 Z";

const FULL_VIEWBOX = "0 0 486.01 87.29";
const MARK_VIEWBOX = "0 0 157.15 87.29";

export const BrandLogo = ({
  variant = 'full',
  size = 'md',
  className = '',
  style = {},
  alt = 'GINUM',
  idPrefix
}) => {
  const autoId = useId();
  const cleanAutoId = autoId.replace(/[^a-zA-Z0-9-_]/g, '');
  const prefix = idPrefix || 'ginum-logo';
  const gradientId = `${prefix}-${cleanAutoId}-grad`;

  const sizeClasses = {
    xs: 'h-6',
    sm: 'h-8',
    md: 'h-10',
    lg: 'h-12',
    xl: 'h-14',
    '2xl': 'h-16',
    auto: 'h-auto'
  };

  const chosenHeight = size ? sizeClasses[size] || sizeClasses.md : '';
  const isMarkOnly = variant === 'mark' || variant === 'mark-only' || variant === 'mark-white';
  const isWhite = variant === 'white' || variant === 'mark-white';
  const isNavy = variant === 'navy';

  if (isMarkOnly) {
    return (
      <svg
        viewBox={MARK_VIEWBOX}
        className={`w-auto inline-block ${chosenHeight} ${className}`.trim()}
        style={{ aspectRatio: '157.15 / 87.29', ...style }}
        role="img"
        aria-label={alt}
        xmlns="http://www.w3.org/2000/svg"
        fill="none"
      >
        <title>{alt}</title>
        {!isWhite && (
          <defs>
            <linearGradient id={gradientId} x1="0%" y1="100%" x2="50%" y2="0%">
              <stop offset="0%" stopColor="#1A335A" />
              <stop offset="100%" stopColor="#90C8EC" />
            </linearGradient>
          </defs>
        )}
        <path
          d={MARK_ONLY_PATH}
          fill={isWhite ? '#FFFFFF' : `url(#${gradientId})`}
          fillRule="evenodd"
        />
      </svg>
    );
  }

  return (
    <svg
      viewBox={FULL_VIEWBOX}
      className={`w-auto inline-block ${chosenHeight} ${className}`.trim()}
      style={{ aspectRatio: '486.01 / 87.29', ...style }}
      role="img"
      aria-label={alt}
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
    >
      <title>{alt}</title>
      {!isWhite && (
        <defs>
          <linearGradient id={gradientId} x1="0%" y1="100%" x2="50%" y2="0%">
            <stop offset="0%" stopColor="#1A335A" />
            <stop offset="100%" stopColor="#90C8EC" />
          </linearGradient>
        </defs>
      )}
      <path
        d={FULL_BAR_PATH}
        fill={isWhite ? '#FFFFFF' : `url(#${gradientId})`}
        fillRule="evenodd"
      />
      <path
        d={FULL_WORDMARK_PATH}
        fill={isWhite ? '#FFFFFF' : (isNavy ? '#1A335A' : '#000000')}
        fillRule="evenodd"
      />
    </svg>
  );
};

BrandLogo.propTypes = {
  variant: PropTypes.oneOf(['full', 'full-color', 'white', 'navy', 'mark', 'mark-only', 'mark-white']),
  size: PropTypes.oneOf(['xs', 'sm', 'md', 'lg', 'xl', '2xl', 'auto']),
  className: PropTypes.string,
  style: PropTypes.object,
  alt: PropTypes.string,
  idPrefix: PropTypes.string
};

export default BrandLogo;
